package com.bank.balance.service;

import com.bank.balance.model.Account;
import java.math.BigDecimal;
import java.util.*;

public class BalanceService {
    // In-memory store standing in for a database (native image keeps it simple).
    private final Map<String, Account> store = new HashMap<>();

    public BalanceService() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh", new BigDecimal("1000000.00")));
        store.put("CUR3001", new Account("CUR3001", "Priya",  new BigDecimal("250000.00")));
    }

    public BigDecimal balanceOf(String accountId) {
        Account a = store.get(accountId);
        if (a == null) throw new NoSuchElementException("Unknown account: " + accountId);
        return a.getBalance();
    }
}
