package com.bank.balance;

import com.bank.balance.service.BalanceService;
import java.util.logging.*;

public class BalanceApp {
    private static final Logger log = Logger.getLogger(BalanceApp.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    // Native image compiles THIS reachable graph ahead of time. Starts in ~ms.
    public static void main(String[] args) {
        long start = System.nanoTime();
        var service = new BalanceService();
        log.info(() -> "Rajesh SAV2001 balance: Rs." + service.balanceOf("SAV2001"));
        log.info(() -> "Priya  CUR3001 balance: Rs." + service.balanceOf("CUR3001"));
        long ms = (System.nanoTime() - start) / 1_000_000;
        log.info(() -> "Served in " + ms + " ms (native: process startup is near-instant)");
    }
}
